INSERT INTO `comments` VALUES (7,9,67,'Nguyễn Minh Khuê','Xoài ngọt, đóng gói chắc tay, quét QR thấy rõ lô Hòa Lộc và kho bảo quản.',5,'2026-06-04 12:41:11'),(13,9,50,'Phạm Ngọc Linh','Chất lượng tốt, phù hợp cho bữa ăn gia đình và dễ kiểm tra thông tin truy xuất.',5,'2026-06-04 13:13:16'),(14,10,47,'Nguyễn Minh Anh','Chất lượng tốt, phù hợp cho bữa ăn gia đình và dễ kiểm tra thông tin truy xuất.',5,'2026-06-04 13:13:16'),(15,11,47,'Nguyễn Minh Anh','Hàng nhận được tươi, nguồn gốc rõ ràng. Lần sau tôi vẫn muốn đặt tiếp sản phẩm này.',4,'2026-06-04 13:13:16'),(16,12,48,'Trần Gia Hân','Chất lượng tốt, phù hợp cho bữa ăn gia đình và dễ kiểm tra thông tin truy xuất.',5,'2026-06-04 13:13:16'),(17,13,48,'Trần Gia Hân','Hàng nhận được tươi, nguồn gốc rõ ràng. Lần sau tôi vẫn muốn đặt tiếp sản phẩm này.',4,'2026-06-04 13:13:16'),(18,14,48,'Trần Gia Hân','Chất lượng tốt, phù hợp cho bữa ăn gia đình và dễ kiểm tra thông tin truy xuất.',5,'2026-06-04 13:13:16'),(19,15,49,'Lê Quốc Bảo','Sản phẩm có chất lượng tốt, phù hợp cho bữa ăn gia đình và dễ dàng kiểm tra thông tin truy xuất nguồn gốc.',5,'2026-06-04 13:13:16'),(20,16,50,'Phạm Ngọc Linh','Sản phẩm có chất lượng tốt, phù hợp cho bữa ăn gia đình và dễ dàng kiểm tra thông tin truy xuất nguồn gốc.',5,'2026-06-04 13:13:16'),(21,17,50,'Phạm Ngọc Linh','Sản phẩm nhận được còn tươi, nguồn gốc rõ ràng. Tôi sẽ tiếp tục đặt mua sản phẩm này trong lần sau.',4,'2026-06-04 13:13:16'),(22,26,47,'Nguyễn Minh Anh','Sản phẩm có chất lượng tốt, phù hợp cho bữa ăn gia đình và dễ dàng kiểm tra thông tin truy xuất nguồn gốc.',5,'2026-06-04 13:13:16'),(24,56,1,'Nguyễn Quốc Toàn','Sản phẩm có chất lượng tốt, phù hợp cho bữa ăn gia đình và dễ dàng kiểm tra thông tin truy xuất nguồn gốc.',5,'2026-06-04 13:13:16'),(25,58,67,'Nguyễn Minh Khuê','Mít nhận được thơm, phần ruột đẹp và đóng gói chắc. Tôi đã đặt thử cho gia đình và thấy chất lượng ổn.',5,'2026-06-04 13:17:02'),(28,9,NULL,'Nguyễn Minh Khuê','Hàng đúng chất lượng, đóng gói sạch và có QR truy xuất rõ lô. Tôi đặt lại vì nguồn gốc và thời gian giao rất ổn.',4,'2026-06-05 12:00:00'),(29,9,67,'Nguyễn Minh Khuê','Đã kiểm thử đặt hàng, tồn kho và truy xuất nguồn gốc. Sản phẩm này hiển thị ổn trong dữ liệu bán hàng mới.',5,'2026-06-05 13:00:00'),(30,10,NULL,'Michael Johnson','The shipment arrived in good condition. Packaging, origin documents, and QR traceability were clear enough for our receiving team.',5,'2026-06-05 12:01:15'),(31,11,NULL,'佐藤健二','品質が安定していて、梱包も丁寧でした。QR追跡で産地とロットを確認でき、輸入確認がスムーズでした。',5,'2026-06-05 12:02:30'),(32,11,67,'Nguyễn Minh Khuê','Đã kiểm thử đặt hàng, tồn kho và truy xuất nguồn gốc. Sản phẩm này hiển thị ổn trong dữ liệu bán hàng mới.',5,'2026-06-05 13:02:30'),(33,12,NULL,'김민지','상품 상태가 좋고 포장이 깔끔했습니다. QR 추적으로 산지와 로트를 확인할 수 있어 신뢰가 갔습니다.',5,'2026-06-05 12:03:45'),(34,13,NULL,'李伟','货品新鲜度和包装都很好，二维码可以清楚追溯产地和批次，收货团队很满意。',5,'2026-06-05 12:05:00'),(35,13,67,'Nguyễn Minh Khuê','Đã kiểm thử đặt hàng, tồn kho và truy xuất nguồn gốc. Sản phẩm này hiển thị ổn trong dữ liệu bán hàng mới.',5,'2026-06-05 13:05:00'),(36,14,NULL,'Anna Schneider','Die Ware kam sauber verpackt an. Herkunft, Charge und Kühlkette waren über den QR-Nachweis gut nachvollziehbar.',4,'2026-06-05 12:06:15'),(37,15,NULL,'Claire Dubois','Produit bien emballé, qualité régulière et traçabilité QR claire. Les documents de lot sont faciles à vérifier.',5,'2026-06-05 12:07:30'),(38,15,67,'Nguyễn Minh Khuê','Đã kiểm thử đặt hàng, tồn kho và truy xuất nguồn gốc. Sản phẩm này hiển thị ổn trong dữ liệu bán hàng mới.',5,'2026-06-05 13:07:30'),(39,16,NULL,'ณัฐพงศ์','สินค้าแพ็กมาดี คุณภาพสม่ำเสมอ และตรวจสอบแหล่งที่มากับล็อตผ่าน QR ได้ชัดเจน',5,'2026-06-05 12:08:45'),(40,17,NULL,'عمر المنصوري','وصلت الشحنة بحالة جيدة، والتغليف واضح. رمز QR يوضح المنشأ ورقم الدفعة بشكل مناسب.',5,'2026-06-05 12:10:00'),(41,17,67,'Nguyễn Minh Khuê','Đã kiểm thử đặt hàng, tồn kho và truy xuất nguồn gốc. Sản phẩm này hiển thị ổn trong dữ liệu bán hàng mới.',5,'2026-06-05 13:10:00'),(42,26,NULL,'Nguyễn Minh Khuê','Hà