--
-- Table structure for table `product`
--

DROP TABLE IF EXISTS `product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) DEFAULT NULL,
  `price` bigint DEFAULT NULL,
  `category_id` int DEFAULT NULL,
  `stock` int DEFAULT '0',
  `image` varchar(255) DEFAULT NULL,
  `description` text,
  `origin` varchar(255) DEFAULT NULL COMMENT 'Nguồn gốc',
  `supplier` varchar(150) DEFAULT NULL COMMENT 'Nhà cung cấp',
  `standard` varchar(100) DEFAULT NULL COMMENT 'Tiêu chuẩn (VietGAP...)',
  `harvest_date` date DEFAULT NULL COMMENT 'Ngày thu hoạch',
  `expiry_days` int DEFAULT '10' COMMENT 'Hạn sử dụng (số ngày)',
  `warehouse_address` text COMMENT 'Địa chỉ kho',
  `is_flash_sale` tinyint DEFAULT '0',
  `flash_discount` int DEFAULT '0',
  `is_featured` tinyint DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `category_id` (`category_id`),
  CONSTRAINT `product_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `category` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

