INSERT INTO `product` VALUES (9,'Xoài cát Hòa Lộc',45000,2,556,'1777997723_41907ebe5083417aac301069777c15ef.jpg','Xoài cát Hòa Lộc tuyển chọn theo lô, có QR truy xuất vùng trồng, phù hợp bán nội địa và xuất khẩu.','Vùng trồng Hòa Lộc - Cái Bè, Tiền Giang','HTX Xoài cát Hòa Lộc Tiền Giang','GlobalGAP','2026-06-04',10,'Khu công nghiệp Tân Phú Trung, Củ Chi, TP.HCM',1,12,1),(10,'Chuối già Nam Mỹ',20000,2,1729,'1777997710_e48e0b0b0f3b96f2cbf79d357a2d2c88.jpg','Chuối già Nam Mỹ canh tác theo quy trình xuất khẩu. Quả đều đẹp, thịt chắc, cung cấp năng lượng nhanh và nhiều kali cho cơ thể.','Vùng trồng chuối Long An','Công ty Nông nghiệp Hoàng Anh','VietGAP-LA-2025','2026-05-10',10,'Kho Aethera - TP.HCM',0,0,1),(11,'Táo Mỹ nhập khẩu',65000,2,1902,'1777997695_8f6d00472013810d87ab3e9f557aca1c.jpg','Táo Mỹ nhập khẩu chính ngạch, giòn ngọt, hương thơm đặc trưng. Được bảo quản trong môi trường lạnh tối ưu để giữ trọn độ tươi ngon khi đến tay khách hàng.','Trang trại Apple Farm, Washington, Mỹ','Nhập khẩu trái cây Global Fresh','USDA Organic / GlobalGAP','2026-04-20',10,'Kho Aethera - TP.HCM',0,0,1),(12,'Cam sành',30000,2,1074,'1777997684_96aa79561f58d1d59400fec3f99f9ad2.jpg','Cam sành Tiền Giang vỏ mọng, nhiều nước, vị chua ngọt đậm đà. Nguồn cung cấp Vitamin C tự nhiên dồi dào, giúp tăng cường sức đề kháng.','Vùng trồng Hòa Lộc, Cái Bè, Tiền Giang','HTX Xoài cát Hòa Lộc','GlobalGAP-TG-2026','2026-05-08',10,'Kho lạnh Aethera - Tiền Giang',0,0,1),(13,'Bưởi da xanh',50000,2,1247,'1777997675_b8d24d55234064c11854158688081ff8.jpg','Bưởi da xanh ruột hồng, tép bưởi mọng nước, không hạt, vị ngọt đậm. Là món quà quý từ vùng đất phù sa Hòa Lộc.','Vùng trồng Hòa Lộc, Cái Bè, Tiền Giang','HTX Xoài cát Hòa Lộc','GlobalGAP-TG-2026','2026-05-08',10,'Kho lạnh Aethera - Tiền Giang',0,0,0),(14,'Nho xanh',90000,2,1420,'1777997655_b1bf8e96727a0f050daac140d33e00a7.jpg','Nho xanh tươi ngon, quả giòn, vị ngọt thanh mát lạnh. Một trong những loại trái cây được ưa chuộng nhất tại Aethera Supply.','Vùng nho Ninh Thuận, Việt Nam','Hợp tác xã Nho Ninh Thuận','VietGAP-NT-2025','2026-05-12',10,'Kho Aethera - TP.HCM',0,0,0),(15,'Hạt điều',120000,5,1593,'1777997634_78054eaf3e7f91130763aea3dcfb48fc.jpg','Hạt điều rang muối thượng hạng, hạt to, giòn tan, vị béo bùi đặc trưng của vùng đất đỏ Bình Phước. Giàu dinh dưỡng và tốt cho tim mạch.','Vùng nguyên liệu Bình Phước','Công ty Điều sạch Bình Phước','HACCP Standard','2026-05-01',10,'Kho Aethera - TP.HCM',0,0,0),(16,'Hạt hướng dương',45000,5,1000,'1777997624_ae4d22b41c025dd5fe1ead7b8a4517aa.jpg','Hạt hướng dương loại to, hạt chắc, rang thơm nhẹ, không dùng phẩm màu. Món ăn nhẹ lý tưởng cho các buổi họp mặt.','Trang trại hướng dương Nghệ An','Công ty Nông sản sạch miền Trung','ISO 22000:2018','2026-05-05',10,'Kho Aethera - TP.HCM',0,0,1),(17,'Đậu phộng',35000,5,1939,'1777997611_71ea37395d608ec7774292af1003671e.jpg','Đậu phộng quê rang giòn, hạt nhỏ nhưng béo thơm đậm đà. Được tuyển chọn kỹ lưỡng, không có hạt mốc hay sâu mọt.','Vùng trồng đậu phộng Đức Hòa, Long An','Đặc sản Long An Farm','Tiêu chuẩn hữu cơ nội địa','2026-05-07',10,'Kho Aethera - TP.HCM',0,0,1),(26,'Gạo thuộc giống OM18',60000,4,1494,'product_1780014610_a857cf6e709e.jpg','Lúa giống OM18 chất lượng cao, khả năng chịu mặn tốt, năng suất ổn định. Gạo thành phẩm thơm nhẹ, mềm cơm, đạt chuẩn xuất khẩu.','Cánh đồng mẫu lớn An Giang','Tập đoàn Lộc Trời','Chuẩn giống lúa quốc gia','2026-04-15',10,'Kho Aethera - TP.HCM',0,0,0),(34,'Cà Phê Rang Say Đắc Nông',280000,5,1877,'1777998071_691066ad1ad55d660660535fa2c28dc8.jpg','Cà phê rang xay Đắk Nông nguyên chất 100%. Hương vị đắng đậm, hậu vị ngọt, hương thơm nồng nàn từ những hạt cà phê đạt chuẩn 4C.','Trang trại Nông sản Đắk Nông','Liên minh Cà phê Tây Nguyên','4C-Certification','2026-04-25',10,'Tổng kho Aethera - TP.HCM',0,0,0),(36,'Tiêu đen Hà Tiên',25000,6,1222,'1778226850_timthumb.jpg','Tiêu đen Hà Tiên hạt chắc, vị cay nồng và mùi thơm đặc trưng không lẫn vào đâu được. Sản phẩm được phơi khô tự nhiên, không tạp chất.','Trang trại hồ tiêu Hà Tiên, Kiên Giang','Đặc sản vùng miền Kiên Giang','Chỉ dẫn địa lý Hà Tiên','2026-05-01',10,'Kho Aethera - TP.HCM',0,0,1),(49,'Măng cụt Lái Thiêu',85000,2,1469,'1779215063_0c6a9fcbdcb430d701c1a578b80070be.jpg','Măng cụt Lái Thiêu vỏ tím đậm, múi trắng dày, vị ngọt thanh, đạt chuẩn VietGAP.','Thuận An, Bình Dương','HTX Trái cây Lái Thiêu','VietGAP-BD-2026','2026-05-19',10,'TP.HCM',0,0,0),(50,'Bơ sáp Đắk Lắk',95000,2,1642,'1779215464_11fd6a84580a526d9d05acbb39e54ea6.jpg','Bơ sáp cơm vàng dẻo, béo ngậy, đạt chuẩn GlobalGAP.','Buôn Ma Thuột, Đắk Lắk','HTX Nông sản Tây Nguyên','GlobalGAP-DL-2026','2026-05-19',10,'TP.HCM',0,0,0),(51,'Dâu tây Đà Lạt',140000,2,1815,'1779215701_b9515547b7f5581334386cbb4aedc7d0.jpg','Dâu tây Đà Lạt loại premium, mọng nước, vị ngọt thanh.','Phường 7, TP. Đà Lạt','Trang trại FreshBerry Đà Lạt','VietGAP-DL-2026','2026-05-19',10,'TP.HCM',1,1,0),(52,'Ổi Ruby Long An',38000,2,1988,'5dc158ad0c6d91866b24ede8d3a83cb6.jpg','Ổi ruby ruột đỏ, giòn ngọt, phù hợp bán lẻ và xuất khẩu.','Đức Hòa, Long An','HTX Trái cây Long An','VietGAP-LA-2026','2026-05-19',10,'Kho Aethera - TP.HCM',1,1,0),(53,'Chôm chôm Java',55000,2,1160,'e16723b32e1ba8f84e5ac744724d86e7.jpg','Chôm chôm Java trái to, vỏ đỏ đẹp, vị ngọt thanh.','Cái Bè, Tiền Giang','HTX Chôm chôm miền Tây','','2026-05-01',10,'TP.HCM',1,1,0),(54,'Gừng hữu cơ Kon Tum',42000,6,10,'fb106a3a17bc39bf202550a3bd3ee3b8.jpg','Gừng hữu cơ củ già, cay thơm, dùng làm gia vị và dược liệu.','Đắk Hà, Kon Tum','Nông trại hữu cơ Kon Tum','Organic Farm VN','2026-05-19',15,'Kho Aethera - Bình Dương',1,1,0),(55,'Me Thái',68000,2,10,'5e938077850b41348f7e54b652f3d9f2.jpg','Me Thái quả dài, vị ngọt tự nhiên, ít xơ.','Trảng Bom, Đồng Nai','HTX Nông sản miền Đông','ThaiFarm Standard','2026-05-19',10,'Kho Aethera - TP.HCM',1,1,0),(56,'Sầu riêng Ri6',180000,2,1679,'019d328b25e28f07cecec2cea8e1fb87.jpg','Sầu riêng Ri6 cơm vàng, hạt lép, mùi thơm đặc trưng.','Cai Lậy, Tiền Giang','HTX Sầu riêng Cai Lậy','GlobalGAP-RI6-2026','2026-05-19',7,'Kho Aethera - Tiền Giang',1,1,0),(57,'Thanh long ruột đỏ',32000,2,1852,'c57d5a00e7d819e0910bc73b145a8b88.jpg','Thanh long ruột đỏ Bình Thuận, màu đẹp, vị ngọt nhẹ.','Hàm Thuận Nam, Bình Thuận','HTX Thanh long Bình Thuận','VietGAP-BT-2026','2026-05-19',10,'Kho Aethera - Bình Dương',1,1,0),(58,'Mít Thái',45000,2,1024,'6b2ed0273ace5e2b1bfcf6b183d11ec6.jpg','Mít Thái múi vàng, giòn ngọt, đóng gói sạch.','Châu Thành, Hậu Giang','HTX Trái cây Hậu Giang','VietGAP-HG-2026','2026-05-19',8,'Kho Aethera - TP.HCM',1,1,0),(60,'Chanh không hạt',30000,6,10,'f0b0c0620f403658e0cfe80cafabc54e.jpg','Chanh không hạt Long An, nhiều nước, vỏ mỏng.','Bến Lức, Long An','HTX Chanh Long An','VietGAP-LA-2026','2026-05-19',10,'Kho Aethera - TP.HCM',1,1,0),(61,'Dưa hấu Long An',18000,2,1543,'572e446e7ecd1261d1973b7e11f1d622.jpg','Dưa hấu ruột đỏ, trái mọng nước, vị ngọt mát.','Tân Trụ, Long An','HTX Dưa hấu Long An','VietGAP-LA-2026','2026-05-19',7,'Kho Aethera - TP.HCM',1,1,0),(62,'ỚT PERU',200000,6,1716,'1779298583_68b5006be62578d39f1af1681dc2ab4d.jpg','ớt trồng ở thời tiết hanh khô vùng PERU xa xôi mang đến vị cay bùng nổi','Vùng sa mạc ven biển Ba Tư','Công Ty phân phối nông sản BA TƯ','VietGAP-DL-2026','2026-05-20',10,'TP.HCM',1,1,0),(64,'gạo ST25',25000,4,1061,'product_1780594332_0de7411a119e.jpg','Sản phẩm được tạo từ lô thu hoạch gạo ST25, dùng cho quản lý kho và truy xuất nguồn gốc.','Tháp 10','HTX Tỉnh Đồng Tháp','VietGAP-BD-2026','2026-05-29',10,'TP.HCM',0,0,0),(65,'Gạo Hương Lài',23000,4,10,'product_1780601100_d90fcff4ba0b.jpg','','cần đước long an','HTX Huyện cần đước tỉnh long an','VietGAP-BD-2026','2026-06-04',10,'TP.HCM',0,0,0),(77,'Khoai lang',20000,4,10,'product_1780617525_a6d2584b821e.jpg','Khoai lang được thu hoạch từ vùng trồng Châu Thành, Đồng Tháp, nơi có điều kiện đất đai phù hợp cho cây khoai lang phát triển. Sản phẩm được chọn lọc từ các củ chắc, vỏ đẹp, ít trầy xước, phù hợp để luộc, hấp, nướng hoặc chế biến món ăn hằng ngày.','Tháp 10 Đồng Tháp','HTX Huyện Tháp 10 Tỉnh Đồng Tháp','Global GAP','2026-06-05',10,'TP.HCM',0,0,0),(78,'Bắp ngô',23000,5,10,'product_1780619506_c9e4bce41ca8.jpg','Bắp ngô được tuyển chọn từ những trái tươi, hạt đều, chắc và có màu sắc đẹp. Khi chế biến, bắp có vị ngọt thanh, mùi thơm nhẹ, hạt mềm dẻo và dễ ăn. Sản phẩm phù hợp cho bữa ăn gia đình, món ăn vặt hoặc chế biến thành các món như bắp luộc, bắp nướng, súp bắp, sữa bắp và các món xào.','Cao lãnh đồng tháp','HTX Huyện  Cao Lãnh','Global GAP','2026-06-05',10,'TP.HCM',0,0,0),(79,'Gạo huyết rồng',110000,4,10,'product_1780630394_9f9e2cbaf02b.jpg','Sản phẩm được tạo từ lô thu hoạch Gạo huyết rồng, dùng cho quản lý kho và truy xuất nguồn gốc.','Long an','HTX long an','GlobalGAP-DL-2026','2026-06-05',10,'TP.HCM',0,0,0),(80,'Ca Cao',103000,2,100,'product_1780637517_4887de818b5c.jpg','Ca cao là nông sản có hương thơm đặc trưng, vị đắng nhẹ và màu sắc tự nhiên. Sản phẩm phù hợp để chế biến bột ca cao, socola, đồ uống, bánh kẹo và nhiều sản phẩm thực phẩm khác. Hạt ca cao được chọn lọc, bảo quản khô ráo nhằm giữ chất lượng và hương vị ổn định.','Tháp chàm','HTX bến tre','VietGAP-DL-2026','2026-06-05',10,'TP.HCM',0,0,0);
