--
-- Table structure for table `product_batch`
--

DROP TABLE IF EXISTS `product_batch`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_batch` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int DEFAULT NULL,
  `supplier_id` int DEFAULT NULL,
  `batch_code` varchar(100) DEFAULT NULL,
  `qr_code` varchar(255) DEFAULT NULL,
  `warehouse_id` int NOT NULL,
  `planting_date` date DEFAULT NULL,
  `harvest_date` date DEFAULT NULL,
  `cultivation_method` text,
  `fertilizer` text,
  `pesticide` text,
  `area` decimal(10,2) DEFAULT '0.00',
  `quantity` int DEFAULT '0',
  `remaining_quantity` int DEFAULT '0',
  `quality_standard` varchar(100) DEFAULT NULL,
  `storage_temperature` decimal(5,2) DEFAULT NULL,
  `storage_humidity` decimal(5,2) DEFAULT NULL,
  `preservation_method` varchar(150) DEFAULT NULL,
  `status` varchar(30) DEFAULT 'stored',
  `notes` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `unit` varchar(20) DEFAULT 'kg',
  `certificate_file` varchar(255) DEFAULT NULL,
  `supplier_order_id` int DEFAULT NULL,
  `import_price` decimal(12,2) DEFAULT '0.00',
  `confirmed_quantity` decimal(12,2) DEFAULT '0.00',
  `payable_amount` decimal(12,2) DEFAULT '0.00',
  `payment_status` enum('unpaid','partial','paid') DEFAULT 'unpaid',
  `product_name_snapshot` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `batch_code` (`batch_code`),
  UNIQUE KEY `qr_code` (`qr_code`),
  KEY `idx_product_batch_product_id` (`product_id`),
  KEY `idx_product_batch_supplier_id` (`supplier_id`),
  KEY `idx_product_batch_warehouse_id` (`warehouse_id`),
  CONSTRAINT `fk_product_batch_product` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_product_batch_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `supplier` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_product_batch_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_product_batch_quantity_nonnegative` CHECK ((`quantity` >= 0)),
  CONSTRAINT `chk_product_batch_remaining_nonnegative` CHECK ((`remaining_quantity` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=125 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

