DROP TABLE IF EXISTS `product_traceability`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_traceability` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int DEFAULT NULL,
  `farm_name` varchar(255) DEFAULT NULL,
  `harvest_date` date DEFAULT NULL,
  `certification` varchar(100) DEFAULT NULL,
  `origin_location` varchar(255) DEFAULT NULL,
  `packaging_date` date DEFAULT NULL,
  `batch_id` int DEFAULT NULL,
  `storage_info` text,
  `transport_info` text,
  `product_name_snapshot` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_product_trace` (`product_id`),
  KEY `idx_product_traceability_batch_id` (`batch_id`),
  CONSTRAINT `fk_product_trace` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_product_traceability_batch` FOREIGN KEY (`batch_id`) REFERENCES `product_batch` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

