--
-- Table structure for table `supplier_orders`
--

DROP TABLE IF EXISTS `supplier_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `supplier_orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `supplier_id` int NOT NULL,
  `warehouse_id` int DEFAULT NULL,
  `status` enum('pending','supplier_submitted','warehouse_confirmed','completed','paid','rejected','cancelled') DEFAULT 'pending',
  `total_amount` decimal(12,2) DEFAULT '0.00',
  `paid_amount` decimal(12,2) DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `requested_quantity` decimal(12,2) DEFAULT '0.00',
  `suggested_import_price` decimal(12,2) DEFAULT '0.00',
  `requested_product_name` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_supplier_orders_supplier_id` (`supplier_id`),
  KEY `idx_supplier_orders_warehouse_id` (`warehouse_id`),
  KEY `idx_supplier_orders_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

